"""Offline, read-only review of the exact structured exports; no external libraries."""
import json


def render(model, artifacts, media=None):
    payload = json.dumps({"model": model, "artifacts": artifacts, "media": media or {}}, ensure_ascii=False)
    payload = payload.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return PAGE.replace("__PAYLOAD__", payload)


